import os
from flask import Flask, jsonify, render_template_string, Response, abort
app = Flask(__name__, static_folder=None)
HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">\n<meta name="theme-color" content="#1555e8"><title>BlueLedger · On-chain expense journal</title>\n<link rel="stylesheet" href="{{ url_for(\'static\', filename=\'style.css\') }}">\n<script id="config" type="application/json">{{ {\'contractAddress\': contract_address}|tojson }}</script>\n<script src="{{ url_for(\'static\', filename=\'app.js\') }}" defer></script>\n</head>\n<body>\n<main>\n<nav><a class="brand" href="/">▣ BlueLedger</a><span class="pill">SEPOLIA TESTNET</span></nav>\n<header><p class="eyebrow">YOUR WALLET. YOUR RECORDS.</p><h1>Small expenses.<br>Lasting records.</h1><p class="intro">A simple on-chain expense journal. Connect your wallet, log an expense, and keep a verifiable record.</p></header>\n<div id="status" class="status" role="status" aria-live="polite">Connect your wallet to start. Use sample expenses: blockchain records are public.</div>\n<div class="layout">\n<section class="card setup"><h2><span class="step">01</span> Connect your ledger</h2><label for="address">ExpenseLedger contract address</label><input id="address" placeholder="0x…" spellcheck="false" autocomplete="off"><small>The new ExpenseLedger contract on Sepolia. Your old SimpleStorage address will not work.</small><button id="connect">Connect MetaMask</button><button id="deploy" class="secondary">Create my ledger (one-time)</button><small>No contract yet? Create one using Sepolia test ETH, then connect. Your wallet will request confirmation.</small><a id="share" class="textlink" hidden>Open shareable ledger link ↗</a><p class="detail">Wallet <span id="wallet">Not connected</span></p><p class="detail">Network <span id="network">—</span></p><p class="mobile">On your phone, open this website in the <strong>MetaMask app browser</strong>.</p><a id="mobile-link" class="textlink" hidden>Open in MetaMask ↗</a></section>\n<section class="card summary"><p class="eyebrow">MY TOTAL RECORDED EXPENSES</p><div id="total" class="total">S$ —</div><p><span id="count">—</span> records on Sepolia</p><div class="summary-note">Records only · No SGD or ETH transfer<br>Test ETH is used only for network fees.</div><button id="refresh" class="secondary" disabled>Refresh from blockchain</button></section>\n<section class="card"><h2><span class="step">02</span> Record an expense</h2><form id="expense-form"><label for="amount">Amount (SGD)</label><input id="amount" type="text" inputmode="decimal" placeholder="e.g. 8.50" required><label for="category">Category</label><select id="category"><option value="0">Food & drinks</option><option value="1">Transport</option><option value="2">Study</option><option value="3">Shopping</option><option value="4">Other</option></select><label for="note">Short note (optional)</label><input id="note" maxlength="120" placeholder="e.g. Lunch on campus"><small>Up to 120 UTF-8 bytes. Do not enter personal or sensitive information.</small><button id="save" disabled>Save expense on blockchain</button></form><small>Confirm in MetaMask. Records cannot be edited or deleted.</small><a id="tx" class="textlink" target="_blank" rel="noopener noreferrer" hidden>View transaction ↗</a></section>\n<section class="card history"><div class="section-title"><h2><span class="step">03</span> My history</h2><span>Newest first</span></div><div id="records"><p class="empty">Your confirmed expenses will appear here.</p></div><button id="more" class="secondary" hidden disabled>Load older records</button></section>\n</div><footer>BlueLedger · An educational DApp by Xiaotong Wang<br>Flask serves the page. Your wallet signs. Sepolia stores the records.</footer>\n</main>\n</body></html>\n'
ASSETS = {'style.css': ':root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#152747;background:#f3f6fc;font-synthesis:none}*{box-sizing:border-box}body{margin:0}main{max-width:1080px;margin:auto;padding:28px 24px}nav{display:flex;justify-content:space-between;align-items:center;gap:10px}.brand{text-decoration:none;font-size:24px;font-weight:800;color:#1555e8}.pill{background:#e5edff;color:#2254b8;border-radius:30px;padding:8px 11px;font-size:10px;font-weight:800;letter-spacing:1px}header{padding:48px 0 28px;max-width:680px}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:800;color:#52709e}h1{font-size:clamp(36px,6vw,60px);line-height:1.08;letter-spacing:-2px;margin:16px 0 20px}h2{font-size:18px;margin:0 0 24px}.intro{font-size:17px;line-height:1.65;color:#60708a;max-width:570px}.layout{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:white;border:1px solid #e1e8f3;border-radius:20px;padding:27px;min-width:0}.step{color:#7f9bcb;font-size:12px;margin-right:10px}.status{padding:15px 18px;border-radius:12px;margin-bottom:22px;background:#e6edfb;color:#29416c;font-size:14px;line-height:1.5;overflow-wrap:anywhere}.status.error{background:#ffebe8;color:#952e25}.status.success{background:#e2f3ee;color:#14624e}label{display:block;font-size:13px;font-weight:650;margin:18px 0 8px}input,select{width:100%;border:1px solid #d5dfee;background:#fbfcff;border-radius:10px;padding:13px;font:inherit;font-size:16px;color:#152747}input:focus,select:focus{outline:2px solid #7ea7ff;outline-offset:2px}button{display:block;width:100%;margin:18px 0 10px;border:0;border-radius:10px;background:#1555e8;color:white;font:inherit;font-size:14px;font-weight:700;padding:14px;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}.secondary{background:#edf2fc;color:#22467c}small{display:block;color:#6e7f99;font-size:12px;line-height:1.6;margin-top:8px}.detail{display:flex;justify-content:space-between;font-size:12px;color:#74849a;gap:12px}.detail span{color:#233f68;overflow-wrap:anywhere}.mobile{border-top:1px solid #edf1f8;padding-top:15px;font-size:12px;line-height:1.6;color:#617492}.summary{background:#1555e8;color:white;display:flex;flex-direction:column;justify-content:center}.summary .eyebrow{color:#c1d4ff}.total{font-size:clamp(32px,5vw,48px);font-weight:750;letter-spacing:-1px;overflow-wrap:anywhere;margin:10px 0}.summary-note{border-top:1px solid #ffffff33;padding-top:24px;margin-top:24px;color:#dbe6ff;line-height:1.7;font-size:13px}.section-title{display:flex;justify-content:space-between;gap:10px}.section-title>span{font-size:11px;color:#8190a8}.record{border-bottom:1px solid #edf1f8;padding:16px 0}.record-top{display:flex;justify-content:space-between;gap:12px;font-size:14px}.record-top strong{white-space:nowrap}.record p{font-size:13px;color:#526989;overflow-wrap:anywhere;margin:8px 0}.record time{font-size:11px;color:#7b8ca7}.empty{font-size:14px;color:#7d8aa0;line-height:1.6;padding:35px 0}.textlink{display:block;margin-top:14px;color:#1555e8;font-size:13px}footer{text-align:center;color:#7c8ca5;font-size:12px;line-height:1.8;padding:30px 0 12px}[hidden]{display:none!important}@media(max-width:650px){main{padding:20px 16px}.layout{grid-template-columns:1fr}.card{padding:22px}header{padding:30px 0 16px}.brand{font-size:21px}.summary{min-height:240px}}\n', 'app.js': '/* ethers is loaded dynamically so wallet guidance still works if the CDN fails. */\nconst $ = id => document.getElementById(id);\nconst categories = [\'Food & drinks\', \'Transport\', \'Study\', \'Shopping\', \'Other\'];\nconst abi = [\'function appId() pure returns (string)\', \'function addExpense(uint256 amountCents,uint8 category,string note)\', \'function totalSpent(address) view returns (uint256)\', \'function getCount(address) view returns (uint256)\', \'function getExpense(address,uint256) view returns (tuple(uint256 amountCents,uint8 category,string note,uint256 timestamp))\'];\nlet ethers, provider, signer, ledger, account, busy = false, cursor = 0n;\nconst config = JSON.parse($(\'config\').textContent);\nfunction storedAddress() { try { return localStorage.getItem(\'blueledger-address\') || \'\'; } catch { return \'\'; } }\n$(\'address\').value = new URLSearchParams(location.search).get(\'contract\') || config.contractAddress || storedAddress();\nfunction status(message, kind = \'\') { $(\'status\').textContent = message; $(\'status\').className = \'status \' + kind; }\nfunction buttons() {\n  $(\'connect\').disabled = busy; $(\'deploy\').disabled = busy;\n  $(\'address\').disabled = busy;\n  for (const id of [\'save\',\'refresh\',\'more\']) $(id).disabled = busy || !ledger;\n}\nfunction money(cents) { const value = BigInt(cents); return `S$ ${(value / 100n).toLocaleString(\'en-SG\')}.${(value % 100n).toString().padStart(2, \'0\')}`; }\nfunction parseAmount(raw) {\n  if (!/^(0|[1-9]\\d{0,6})(\\.\\d{1,2})?$/.test(raw)) throw new Error(\'Enter an amount such as 8.50, with at most two decimal places.\');\n  const [whole, fraction = \'\'] = raw.split(\'.\');\n  const cents = BigInt(whole) * 100n + BigInt(fraction.padEnd(2, \'0\'));\n  if (cents < 1n || cents > 100000000n) throw new Error(\'Amount must be between S$ 0.01 and S$ 1,000,000.00.\');\n  return cents;\n}\nfunction friendly(error) {\n  if (error.code === 4001 || error.code === \'ACTION_REJECTED\') return \'Cancelled in MetaMask. No new expense was confirmed.\';\n  if (error.code === \'INSUFFICIENT_FUNDS\') return \'You need Sepolia test ETH in this wallet for the network fee.\';\n  return error.shortMessage || error.reason || error.message || \'Request failed. Please try again.\';\n}\nasync function run(task) { if(busy) return; busy = true; buttons(); try { await task(); } catch(e) { status(friendly(e), \'error\'); } finally { busy = false; buttons(); } }\nfunction renderRecord(e) {\n  const row = document.createElement(\'article\'); row.className = \'record\';\n  const top = document.createElement(\'div\'); top.className = \'record-top\';\n  const cat = document.createElement(\'span\'); cat.textContent = categories[Number(e.category)] || \'Other\';\n  const amount = document.createElement(\'strong\'); amount.textContent = money(e.amountCents);\n  top.append(cat, amount); row.append(top);\n  if(e.note) { const note = document.createElement(\'p\'); note.textContent = e.note; row.append(note); }\n  const time = document.createElement(\'time\'); const d = new Date(Number(e.timestamp) * 1000); time.dateTime = d.toISOString(); time.textContent = d.toLocaleString(); row.append(time);\n  return row;\n}\nasync function page() {\n  const end = cursor > 10n ? cursor - 10n : 0n;\n  const requests = []; for(let i = cursor; i > end; i--) requests.push(ledger.getExpense(account, i - 1n));\n  const entries = await Promise.all(requests);\n  entries.forEach(e => $(\'records\').append(renderRecord(e)));\n  cursor = end; $(\'more\').hidden = cursor === 0n;\n}\nasync function refresh() {\n  const blockTag = await provider.getBlockNumber();\n  const [total, count] = await Promise.all([ledger.totalSpent(account, {blockTag}), ledger.getCount(account, {blockTag})]);\n  $(\'total\').textContent = money(total); $(\'count\').textContent = count.toString();\n  cursor = count; $(\'records\').replaceChildren(); $(\'more\').hidden = true;\n  if(count === 0n) { const p = document.createElement(\'p\'); p.className = \'empty\'; p.textContent = \'No expenses yet. Add your first sample expense.\'; $(\'records\').append(p); }\n  else await page();\n}\n$(\'connect\').onclick = () => run(async () => {\n  ledger = null;\n  if(!window.ethereum) throw new Error(\'Open this URL inside the MetaMask mobile app browser, or use MetaMask on your desktop browser.\');\n  status(\'Connecting to MetaMask…\');\n  ethers ||= await import(\'https://cdn.jsdelivr.net/npm/ethers@6.15.0/+esm\');\n  const address = $(\'address\').value.trim();\n  if(!ethers.isAddress(address)) throw new Error(\'Enter your deployed ExpenseLedger contract address first.\');\n  try { localStorage.setItem(\'blueledger-address\', address); } catch {}\n  await window.ethereum.request({method:\'eth_requestAccounts\'});\n  const chain = await window.ethereum.request({method:\'eth_chainId\'});\n  if(chain !== \'0xaa36a7\') {\n    await window.ethereum.request({method:\'wallet_switchEthereumChain\', params:[{chainId:\'0xaa36a7\'}]});\n  }\n  provider = new ethers.BrowserProvider(window.ethereum);\n  signer = await provider.getSigner(); account = await signer.getAddress();\n  if((await provider.getNetwork()).chainId !== 11155111n) throw new Error(\'Please switch MetaMask to Sepolia and connect again.\');\n  $(\'wallet\').textContent = account.slice(0,6) + \'…\' + account.slice(-4); $(\'network\').textContent = \'Sepolia\';\n  if(await provider.getCode(address) === \'0x\') throw new Error(\'No contract at this address on Sepolia. Deploy ExpenseLedger.sol using your wallet, not Remix VM.\');\n  const candidate = new ethers.Contract(address, abi, signer);\n  try { if(await candidate.appId() !== \'BLUELEDGER_V1\') throw new Error(); }\n  catch { throw new Error(\'This is not an ExpenseLedger contract. Deploy the new ExpenseLedger.sol and use its address.\'); }\n  ledger = candidate;\n  try { localStorage.setItem(\'blueledger-address\', address); } catch {}\n  await refresh(); status(\'Connected. Your records have been loaded from Sepolia.\', \'success\');\n});\n$(\'refresh\').onclick = () => run(async () => { await refresh(); status(\'Records refreshed from Sepolia.\', \'success\'); });\n$(\'more\').onclick = () => run(page);\n$(\'address\').oninput = () => { ledger = null; $(\'total\').textContent = \'S$ —\'; $(\'count\').textContent = \'—\'; $(\'records\').replaceChildren(); $(\'more\').hidden = true; buttons(); status(\'Address changed. Connect again to load this ledger.\'); };\n$(\'expense-form\').onsubmit = event => {\n  event.preventDefault();\n  run(async () => {\n    if(!ledger) throw new Error(\'Connect your wallet and ledger first.\');\n    const amount = parseAmount($(\'amount\').value.trim()); const note = $(\'note\').value.trim();\n    if(new TextEncoder().encode(note).length > 120) throw new Error(\'Note is too long. Use up to 120 UTF-8 bytes (about 40 Chinese characters).\');\n    $(\'tx\').hidden = true; status(\'Confirm the expense transaction in MetaMask…\');\n    const tx = await ledger.addExpense(amount, Number($(\'category\').value), note);\n    $(\'tx\').href = \'https://sepolia.etherscan.io/tx/\' + tx.hash; $(\'tx\').hidden = false;\n    status(\'Transaction submitted. Waiting for blockchain confirmation…\');\n    let receipt;\n    try { receipt = await tx.wait(); }\n    catch(e) { if(e.code === \'TRANSACTION_REPLACED\' && !e.cancelled) { receipt = e.receipt; $(\'tx\').href = \'https://sepolia.etherscan.io/tx/\' + receipt.hash; } else throw e; }\n    if(!receipt || receipt.status !== 1) throw new Error(\'Transaction did not succeed. Check the transaction link.\');\n    $(\'amount\').value = \'\'; $(\'note\').value = \'\';\n    try { await refresh(); status(\'Expense confirmed and saved on Sepolia.\', \'success\'); }\n    catch { status(\'Expense confirmed. Refresh failed; click Refresh from blockchain. Do not submit the expense again.\', \'success\'); }\n  });\n};\nif(location.protocol === \'https:\') { $(\'mobile-link\').href = \'https://metamask.app.link/dapp/\' + location.host + location.pathname + location.search; $(\'mobile-link\').hidden = false; }\nwindow.ethereum?.on?.(\'accountsChanged\', () => location.reload());\nwindow.ethereum?.on?.(\'chainChanged\', () => location.reload());\nbuttons();\n\nconst deploymentBytecode = "";\n\nfunction shareLink(address) {\n  const url = new URL(location.href); url.searchParams.set(\'contract\', address);\n  $(\'share\').href = url.href; $(\'share\').hidden = false;\n}\nif (/^0x[a-fA-F0-9]{40}$/.test($(\'address\').value)) shareLink($(\'address\').value);\n$(\'deploy\').onclick = () => run(async () => {\n  if(!window.ethereum) throw new Error(\'Open this website in the MetaMask app browser to create your ledger.\');\n  ethers ||= await import(\'https://cdn.jsdelivr.net/npm/ethers@6.15.0/+esm\');\n  await window.ethereum.request({method:\'eth_requestAccounts\'});\n  const chain = await window.ethereum.request({method:\'eth_chainId\'});\n  if(chain !== \'0xaa36a7\') {\n    await window.ethereum.request({method:\'wallet_switchEthereumChain\',params:[{chainId:\'0xaa36a7\'}]});\n    throw new Error(\'Network switched. Tap Create my ledger again after the page reloads.\');\n  }\n  const deploymentProvider = new ethers.BrowserProvider(window.ethereum);\n  const deploymentSigner = await deploymentProvider.getSigner();\n  status(\'Confirm creation of your ledger in MetaMask. This uses Sepolia test ETH for gas.\');\n  const factory = new ethers.ContractFactory(abi, deploymentBytecode, deploymentSigner);\n  const deployed = await factory.deploy();\n  const hash = deployed.deploymentTransaction().hash;\n  const address = await deployed.getAddress();\n  $(\'tx\').href = \'https://sepolia.etherscan.io/tx/\' + hash; $(\'tx\').hidden = false;\n  try { localStorage.setItem(\'blueledger-address\', address); } catch {}\n  $(\'address\').value = address; shareLink(address);\n  status(\'Ledger deployment submitted. Waiting for confirmation. Do not create another ledger.\');\n  await deployed.waitForDeployment();\n  history.replaceState(null, \'\', $(\'share\').href);\n  status(\'Ledger created! Tap Connect MetaMask. Share this page URL with its contract parameter.\', \'success\');\n});\n'}

@app.get('/')
def home():
    return render_template_string(HTML, contract_address=os.getenv('CONTRACT_ADDRESS', '').strip())
@app.get('/static/<filename>', endpoint='static')
def asset(filename):
    if filename not in ASSETS: abort(404)
    return Response(ASSETS[filename], mimetype='text/css' if filename.endswith('.css') else 'text/javascript')
@app.get('/health')
def health(): return jsonify(status='ok')
if __name__ == '__main__': app.run(host='0.0.0.0',port=int(os.getenv('PORT','5000')))
